// src/components/Login.js
import React, { useState } from 'react';
import './Login.css';

const Login = ({ onLogin, error }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  
  const handleSubmit = (e) => {
    e.preventDefault();
    
    // For development, accept any password if using 'doctor' or 'nurse' username
    if (process.env.NODE_ENV === 'development' && 
        (username === 'doctor' || username === 'nurse')) {
      onLogin({ username, password: password || 'password' });
    } else {
      onLogin({ username, password });
    }
  };
  
  return (
    <div className="login-container">
      <div className="login-form-container">
        <div className="login-header">
          <h1>ER Triage System</h1>
          <p>AI-Driven Emergency Room Triage Classification</p>
        </div>
        <form className="login-form" onSubmit={handleSubmit}>
          {error && <div className="error-message">{error}</div>}
          <div className="form-group">
            <label htmlFor="username">Username</label>
            <input
              type="text"
              id="username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              required
            />
          </div>
          <div className="form-group">
            <label htmlFor="password">Password</label>
            <input
              type="password"
              id="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>
          <button type="submit" className="login-button">Login</button>
        </form>
        <div className="login-footer">
          <p>Demo Credentials:</p>
          <div className="demo-credentials">
            <div className="credential">
              <span>Username: <strong>doctor</strong></span>
              <span>Password: <strong>doctorpassword</strong></span>
            </div>
            <div className="credential">
              <span>Username: <strong>nurse</strong></span>
              <span>Password: <strong>nursepassword</strong></span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
